using System.Collections.Generic;\n\nnamespace EnhancedSchoolsMod\n{\n    public class ModConfig\n    {\n        public Dictionary<string, int> SchoolCosts { get; set; } = new() { { \"PublicSchool\", 0 }, { \"BoardingSchool\", 5000 }, { \"ArtsAcademy\", 2500 }, { \"SportsAcademy\", 2500 }, { \"MagicalAcademy\", 10000 } };\n        public List<int> SchoolOperatingDays { get; set; } = new() { 1, 2, 3, 4, 5 };\n        public bool EnableStatsTracking { get; set; } = true;\n        public int TermLengthDays { get; set; } = 28;\n        public int BoardingSchoolReturnDay { get; set; } = 5;\n        public string BoardingSchoolReturnDayName { get; set; } = \"Friday\";\n        public bool ShowSchoolNotifications { get; set; } = true;\n        public bool AllowSchoolChangePerSeason { get; set; } = true;\n        public Dictionary<string, HolidayConfig> HolidaySchedule { get; set; } = new() { { \"SpringBreak\", new HolidayConfig { Season = \"Spring\", StartDay = 13, EndDay = 18, Name = \"Spring Break\" } }, { \"SummerVacation\", new HolidayConfig { Season = \"Summer\", StartDay = 1, EndDay = 28, Name = \"Summer Vacation\" } }, { \"FallBreak\", new HolidayConfig { Season = \"Fall\", StartDay = 15, EndDay = 20, Name = \"Fall Break\" } }, { \"WinterHoliday\", new HolidayConfig { Season = \"Winter\", StartDay = 15, EndDay = 27, Name = \"Winter Holiday\" } } };\n    }\n\n    public class HolidayConfig\n    {\n        public string Season { get; set; } = \"Spring\";\n        public int StartDay { get; set; } = 1;\n        public int EndDay { get; set; } = 1;\n        public string Name { get; set; } = \"Holiday\";\n    }\n}